13	// TestRouteStatusCommandJSON verifies that fiz route-status --help documents
14	// all routing-evidence flags that operators need for --json inspection:
15	// --json (output mode), --profile, --min-power, --max-power (power policy),
16	// --model, --model-ref, --provider (pin constraints).
17	// This confirms AC-2 of FEAT-004: the route-status command surfaces the JSON
18	// evidence envelope via its documented flag set.
19	func TestRouteStatusCommandJSON(t *testing.T) {
20		var stdout, stderr bytes.Buffer
21		cmd := agentcli.MountCLI(
22			agentcli.WithStdout(&stdout),
23			agentcli.WithStderr(&stderr),
24		)
25		cmd.SetArgs([]string{"route-status", "--help"})
26		_ = cmd.Execute()
27	
28		help := stdout.String() + stderr.String()
29		for _, flag := range []string{"--json", "--profile", "--min-power", "--max-power", "--model", "--model-ref", "--provider"} {
30			if !strings.Contains(help, flag) {
31				t.Errorf("route-status help missing routing-evidence flag %q:\n%s", flag, help)
32			}
33		}
34		// Legacy model names must not appear in help: the target surface is power-based routing.
35		for _, legacy := range []string{"code-high", "code-medium"} {
36			if strings.Contains(help, legacy) {
37				t.Errorf("route-status help must not mention legacy name %q:\n%s", legacy, help)
38			}
39		}
40	}
