62	// TestRouteStatusJSONOutputSchema verifies the stable JSON envelope shape that
63	// route-status --json emits when no providers are configured. Even with a
64	// routing error, the envelope must include all documented top-level keys so
65	// operator tooling can parse it unconditionally.
66	func TestRouteStatusJSONOutputSchema(t *testing.T) {
67		workDir := t.TempDir()
68		// Write minimal config (no providers) so the service can be instantiated.
69		cfgPath := workDir + "/.fizeau.yaml"
70		if err := os.WriteFile(cfgPath, []byte("providers: {}\n"), 0o644); err != nil {
71			t.Fatalf("write config: %v", err)
72		}
73	
74		var stdout, stderr bytes.Buffer
75		cmd := agentcli.MountCLI(
76			agentcli.WithStdout(&stdout),
77			agentcli.WithStderr(&stderr),
78		)
79		// Invoke route-status --json with the temp work dir.
80		// No providers → routing will fail, but the JSON envelope is always emitted.
81		cmd.SetArgs([]string{"--work-dir", workDir, "--json", "route-status"})
82		_ = cmd.Execute()
83	
84		out := stdout.String()
85		if out == "" {
86			t.Skip("route-status produced no stdout (possible permission or config issue); skip schema check")
87		}
88	
89		// The output must be valid JSON.
90		var envelope map[string]json.RawMessage
91		if err := json.Unmarshal([]byte(strings.TrimSpace(out)), &envelope); err != nil {
92			t.Fatalf("route-status --json output is not valid JSON: %v\noutput: %s", err, out)
93		}
94	
95		// Required top-level keys per AC-2 of FEAT-004.
96		for _, key := range []string{"candidates", "power_policy"} {
97			if _, ok := envelope[key]; !ok {
98				t.Errorf("route-status JSON envelope missing required key %q:\n%s", key, out)
99			}
100		}
101	}
