112			agentcli.WithStdout(&stdout),
113			agentcli.WithStderr(&stderr),
114		)
115		cmd.SetArgs([]string{"route-status", "--help"})
116		if err := cmd.Execute(); err != nil {
117			t.Fatalf("Execute: %v", err)
118		}
119	
120		help := stdout.String() + stderr.String()
121		for _, want := range []string{"--profile", "--min-power", "--max-power"} {
122			if !strings.Contains(help, want) {
123				t.Fatalf("help output missing %q:\n%s", want, help)
124			}
125		}
126		for _, legacy := range []string{"code-high", "code-medium"} {
127			if strings.Contains(help, legacy) {
128				t.Fatalf("help output must not mention %q:\n%s", legacy, help)
129			}
130		}
131	}
