486			if flag != nil && flag.Changed {
487				if flag.Value.String() == "true" {
488					out = append(out, "--"+name)
489				} else {
490					out = append(out, "--"+name+"="+flag.Value.String())
491				}
492			}
493		}
494		return out
495	}
