// Command fiz is a standalone CLI that wraps the fizeau library.
package main

import (
	"fmt"
	"os"
	"runtime/debug"

	"github.com/DocumentDrivenDX/fizeau/agentcli"
)

// Version info set via -ldflags.
var (
	Version   = "dev"
	BuildTime = ""
	GitCommit = ""
)

func main() {
	version := effectiveVersion(Version)
	vcsCommit, vcsBuildTime, vcsDirty := buildVCSMeta()
	commit := GitCommit
	if commit == "" {
		commit = vcsCommit
	}
	buildTime := BuildTime
	if buildTime == "" {
		buildTime = vcsBuildTime
	}
	cmd := agentcli.MountCLI(
		agentcli.WithStdin(os.Stdin),
		agentcli.WithStdout(os.Stdout),
		agentcli.WithStderr(os.Stderr),
		agentcli.WithVersion(version, buildTime, commit),
		agentcli.WithDirty(vcsDirty),
	)
	args := os.Args[1:]
	if agentcli.NeedsLegacyPassthrough(args) {
		args = append([]string{"--"}, args...)
	}
	cmd.SetArgs(args)
	if err := cmd.Execute(); err != nil {
		if code, ok := agentcli.ExitCode(err); ok {
			os.Exit(code)
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func effectiveVersion(defaultVersion string) string {
	if defaultVersion != "" && defaultVersion != "dev" {
		return defaultVersion
	}
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return defaultVersion
	}
	if info.Main.Version == "" || info.Main.Version == "(devel)" {
		return defaultVersion
	}
	return info.Main.Version
}

// buildVCSMeta reads VCS metadata embedded by the Go toolchain at build time.
// Returns best-effort values; fields are empty/false when the binary was built
// outside a VCS checkout or with -buildvcs=false.
func buildVCSMeta() (commit, buildTime string, dirty bool) {
	info, ok := debug.ReadBuildInfo()
	if !ok {
		return
	}
	for _, s := range info.Settings {
		switch s.Key {
		case "vcs.revision":
			commit = s.Value
		case "vcs.time":
			buildTime = s.Value
		case "vcs.modified":
			dirty = s.Value == "true"
		}
	}
	return
}

