// buildVCSMeta reads VCS metadata from the Go build info, falling back to git
// subprocess when the binary was built without VCS stamping (e.g., go run from
// a linked git worktree where the Go toolchain cannot resolve the gitdir path).
func buildVCSMeta() (commit, buildTime string, dirty bool) {
	info, ok := debug.ReadBuildInfo()
	if ok {
		for _, s := range info.Settings {
			switch s.Key {
			case "vcs.revision":
				commit = s.Value
			case "vcs.time":
				buildTime = s.Value
			case "vcs.modified":
				dirty = s.Value == "true"
			}
		}
	}
	if commit != "" {
		return
	}
	// Fall back to git subprocess for linked worktrees or -buildvcs=false builds.
	if out, err := exec.Command("git", "rev-parse", "HEAD").Output(); err == nil {
		commit = strings.TrimSpace(string(out))
	}
	if commit != "" {
		err := exec.Command("git", "diff-index", "--quiet", "HEAD", "--").Run()
		dirty = err != nil
	}
	return
}
